__global__ void convert_panel_kernel(
        const float* source, __half* compact, int rows, int leading) {
    constexpr int groups_per_row = 512;
    const int64_t total = static_cast<int64_t>(rows) * groups_per_row;
    for (int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x
             + threadIdx.x;
         index < total;
         index += static_cast<int64_t>(gridDim.x) * blockDim.x) {
        const int row = static_cast<int>(index >> 9);
        const int group = static_cast<int>(index & (groups_per_row - 1));
        const float4* source_vectors = reinterpret_cast<const float4*>(
            source + static_cast<int64_t>(row) * leading);
        const float4 first = source_vectors[group * 2];
        const float4 second = source_vectors[group * 2 + 1];
        __half2* destination = reinterpret_cast<__half2*>(
            compact + static_cast<int64_t>(row) * 4096);
        destination[group * 4] = __floats2half2_rn(first.x, first.y);
        destination[group * 4 + 1] = __floats2half2_rn(first.z, first.w);
        destination[group * 4 + 2] = __floats2half2_rn(second.x, second.y);
        destination[group * 4 + 3] = __floats2half2_rn(second.z, second.w);
    }
}

void convert_panel_(torch::Tensor panel, torch::Tensor compact) {
    TORCH_CHECK(panel.is_cuda() && compact.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(panel.scalar_type() == at::kFloat &&
                compact.scalar_type() == at::kHalf,
                "FP32 source and FP16 destination required");
    TORCH_CHECK(panel.dim() == 2 && compact.dim() == 2 &&
                panel.size(0) == compact.size(0) &&
                panel.size(1) == 4096 && compact.size(1) == 4096,
                "4096-column panel required");
    TORCH_CHECK(panel.stride(1) == 1 && compact.is_contiguous(),
                "contiguous inner dimensions required");
    TORCH_CHECK((reinterpret_cast<uintptr_t>(panel.data_ptr<float>()) & 15) == 0,
                "16-byte aligned panel required");
    const int64_t groups = panel.size(0) * 512;
    const int blocks = static_cast<int>(
        std::min<int64_t>((groups + 255) / 256, 4096));
    convert_panel_kernel<<<
        blocks, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            panel.data_ptr<float>(),
            reinterpret_cast<__half*>(compact.data_ptr<at::Half>()),
            static_cast<int>(panel.size(0)),
            static_cast<int>(panel.stride(0)));
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void grouped_pointer_table_kernel(
        float* output,
        int64_t* pointers,
        int batch,
        int n,
        int block,
        int panels) {
    const int index = static_cast<int>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int count = panels * 2 * batch;
    if (index >= count) {
        return;
    }
    const int matrix = index % batch;
    const int table = index / batch;
    const int kind = table & 1;
    const int panel = table >> 1;
    const int start = panel * block;
    const int stop = min(start + block, n);
    const int64_t matrix_base = static_cast<int64_t>(matrix) * n * n;
    const int64_t element = kind == 0
        ? matrix_base + static_cast<int64_t>(start) * (n + 1)
        : matrix_base + static_cast<int64_t>(start) * n + stop;
    pointers[index] = reinterpret_cast<int64_t>(output + element);
}

torch::Tensor grouped_pointer_table_cuda(
        torch::Tensor output, int64_t block_size) {
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
                "CUDA FP32 output required");
    TORCH_CHECK(output.dim() == 3 && output.size(1) == output.size(2) &&
                output.is_contiguous(), "contiguous square batches required");
    const int batch = static_cast<int>(output.size(0));
    const int n = static_cast<int>(output.size(1));
    const int block = static_cast<int>(block_size);
    TORCH_CHECK(block > 0 && block <= n, "invalid block size");
    const int panels = (n + block - 1) / block;
    auto pointers = torch::empty(
        {panels, 2, batch}, output.options().dtype(at::kLong));
    const int count = panels * 2 * batch;
    grouped_pointer_table_kernel<<<
        (count + 127) / 128, 128, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            output.data_ptr<float>(), pointers.data_ptr<int64_t>(),
            batch, n, block, panels);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return pointers;
}

template <int N>
__global__ void fused_left_looking_tile(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int LD = N + 1;
    extern __shared__ float tile[];
    const int tid = threadIdx.x;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
    }
    __syncthreads();

    for (int k = 0; k < N; ++k) {
        if (tid == 0) {
            float diagonal = tile[k * LD + k];
            for (int j = 0; j < k; ++j) {
                const float value = tile[k * LD + j];
                diagonal = fmaf(-value, value, diagonal);
            }
            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
        }
        __syncthreads();

        const float diagonal = tile[k * LD + k];
        for (int row = k + 1 + tid; row < N; row += blockDim.x) {
            float value = tile[row * LD + k];
            for (int j = 0; j < k; ++j) {
                value = fmaf(-tile[row * LD + j], tile[k * LD + j], value);
            }
            tile[row * LD + k] = value / diagonal;
        }
        __syncthreads();
    }

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        dst[index] = tile[row * LD + col];
    }
}

template <int K>
__device__ __forceinline__ void register_cholesky_step_32(
    float (&row_values)[32],
    int lane
) {
    float value = row_values[K];
    #pragma unroll
    for (int j = 0; j < K; ++j) {
        const float pivot = __shfl_sync(0xffffffff, row_values[j], K);
        if (lane >= K) {
            value = fmaf(-row_values[j], pivot, value);
        }
    }

    float inverse = 0.0f;
    if (lane == K) {
        value = sqrtf(fmaxf(value, 1.0e-30f));
        row_values[K] = value;
        inverse = 1.0f / value;
    }
    inverse = __shfl_sync(0xffffffff, inverse, K);
    if (lane > K) {
        row_values[K] = value * inverse;
    }
    if constexpr (K + 1 < 32) {
        register_cholesky_step_32<K + 1>(row_values, lane);
    }
}

__global__ void grouped_warp_cholesky_32(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 32;
    constexpr int LD = 33;
    constexpr int MATRICES_PER_BLOCK = 4;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + warp;
    if (matrix >= batch) {
        return;
    }

    float* tile = storage + warp * N * LD;
    const long long base = static_cast<long long>(matrix) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    #pragma unroll
    for (int row = 0; row < N; ++row) {
        tile[row * LD + lane] = row >= lane
            ? src[row * N + lane]
            : 0.0f;
    }
    __syncwarp();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = tile[lane * LD + col];
    }
    register_cholesky_step_32<0>(row_values, lane);

    #pragma unroll
    for (int col = 0; col < N; ++col) {
        tile[lane * LD + col] = row_values[col];
    }
    __syncwarp();

    #pragma unroll
    for (int row = 0; row < N; ++row) {
        dst[row * N + lane] = tile[row * LD + lane];
    }
}

template <int K>
__device__ __forceinline__ void register_cholesky_step_64(
    float (&row_values)[64],
    float* tile,
    float* inverse,
    int group,
    int lane,
    bool active
) {
    constexpr int LD = 65;
    float value = 0.0f;
    if (active && lane >= K) {
        value = row_values[K];
        #pragma unroll
        for (int j = 0; j < K; ++j) {
            value = fmaf(-row_values[j], tile[K * LD + j], value);
        }
    }

    if (active && lane == K) {
        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
        row_values[K] = diagonal;
        tile[K * LD + K] = diagonal;
        inverse[group] = 1.0f / diagonal;
    }
    __syncthreads();

    if (active && lane > K) {
        value *= inverse[group];
        row_values[K] = value;
        tile[lane * LD + K] = value;
    }
    __syncthreads();

    if constexpr (K + 1 < 64) {
        register_cholesky_step_64<K + 1>(
            row_values, tile, inverse, group, lane, active
        );
    }
}

__global__ void grouped_two_cholesky_64(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 64;
    constexpr int LD = 65;
    constexpr int MATRICES_PER_BLOCK = 2;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    __shared__ float inverse[MATRICES_PER_BLOCK];
    const int group = threadIdx.x / N;
    const int lane = threadIdx.x % N;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + group;
    const bool active = matrix < batch;
    float* tile = storage + group * N * LD;

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        const float* src = input + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            tile[row * LD + lane] = row >= lane
                ? src[row * N + lane]
                : 0.0f;
        }
    }
    __syncthreads();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
    }
    register_cholesky_step_64<0>(
        row_values, tile, inverse, group, lane, active
    );

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        float* dst = output + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            dst[row * N + lane] = tile[row * LD + lane];
        }
    }
}

template <int K>
__device__ __forceinline__ void register_cholesky_step_128(
    float (&row_values)[32],
    float* tile,
    int row,
    int lane
) {
    constexpr int LD = 129;
    float dot = 0.0f;
    if (row >= K) {
        #pragma unroll
        for (int item = 0; item < (K + 3) / 4; ++item) {
            const int col = item * 4 + lane;
            if (col < K) {
                const float left = row_values[item];
                const float right = row == K ? left : tile[K * LD + col];
                dot = fmaf(left, right, dot);
            }
        }
    }
    dot += __shfl_down_sync(0xffffffff, dot, 2, 4);
    dot += __shfl_down_sync(0xffffffff, dot, 1, 4);
    if (row == K && lane == 0) {
        const float diagonal = sqrtf(
            fmaxf(tile[K * LD + K] - dot, 1.0e-30f)
        );
        tile[K * LD + K] = diagonal;
        tile[K * LD + 128] = 1.0f / diagonal;
    }
    __syncthreads();

    float solved = 0.0f;
    if (row > K && lane == 0) {
        solved = (tile[row * LD + K] - dot) * tile[K * LD + 128];
        tile[row * LD + K] = solved;
    }
    solved = __shfl_sync(0xffffffff, solved, 0, 4);
    if (row > K && lane == (K & 3)) {
        row_values[K / 4] = solved;
    }
    __syncthreads();

    if constexpr (K + 1 < 128) {
        register_cholesky_step_128<K + 1>(
            row_values, tile, row, lane
        );
    }
}

__global__ void four_thread_rows_cholesky_128(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int N = 128;
    constexpr int LD = 129;
    extern __shared__ float tile[];
    const int tid = threadIdx.x;
    const int row = tid / 4;
    const int lane = tid % 4;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    const int copy_row = tid / N;
    const int copy_col = tid % N;
    #pragma unroll
    for (int item = 0; item < N / 4; ++item) {
        const int input_row = copy_row + item * 4;
        tile[input_row * LD + copy_col] = input_row >= copy_col
            ? src[input_row * N + copy_col]
            : 0.0f;
    }
    __syncthreads();

    float row_values[N / 4];
    #pragma unroll
    for (int item = 0; item < N / 4; ++item) {
        row_values[item] = tile[row * LD + item * 4 + lane];
    }
    register_cholesky_step_128<0>(row_values, tile, row, lane);

    #pragma unroll
    for (int item = 0; item < N / 4; ++item) {
        const int output_row = copy_row + item * 4;
        dst[output_row * N + copy_col] = tile[output_row * LD + copy_col];
    }
}

template <int N>
void launch_fused_tile(const torch::Tensor& input, torch::Tensor& output) {
    constexpr int shared_bytes = N * (N + 1) * sizeof(float);
    fused_left_looking_tile<N><<<input.size(0), N, shared_bytes>>>(
        input.data_ptr<float>(), output.data_ptr<float>()
    );
}

