__global__ void grouped_upper_copy_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n,
    int batch
) {
    const int total_rows = batch * n;
    const int warp = static_cast<int>(threadIdx.x) >> 5;
    const int lane = static_cast<int>(threadIdx.x) & 31;
    for (int linear_row = static_cast<int>(blockIdx.x) * 16 + warp;
         linear_row < total_rows;
         linear_row += static_cast<int>(gridDim.x) * 16) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int aligned_col = (row + 3) & ~3;
        const int scalar_stop = aligned_col < n ? aligned_col : n;
        for (int col = row + lane; col < scalar_stop; col += 32) {
            output[base + col] = input[base + col];
        }
        const int first_vector = aligned_col / 4;
        const int vector_count = n / 4;
        const float4* input_vectors = reinterpret_cast<const float4*>(
            input + base
        );
        float4* output_vectors = reinterpret_cast<float4*>(output + base);
        for (int vector = first_vector + lane;
             vector < vector_count; vector += 64) {
            output_vectors[vector] = input_vectors[vector];
            const int second = vector + 32;
            if (second < vector_count) {
                output_vectors[second] = input_vectors[second];
            }
        }
    }
}

