__global__ void grouped_diagonal_rankk_kernel(
    const float* __restrict__ panel,
    float* __restrict__ output,
    int macro_count,
    int panel_leading,
    int output_leading,
    long long panel_batch_stride,
    long long output_batch_stride
) {
    using namespace nvcuda;
    const int sample = static_cast<int>(blockIdx.z) / macro_count;
    const int macro = static_cast<int>(blockIdx.z) - sample * macro_count;
    const int warp = static_cast<int>(threadIdx.x) >> 5;
    const int lane = static_cast<int>(threadIdx.x) & 31;
    const int tile_index = static_cast<int>(blockIdx.x) * 8 + warp;
    if (tile_index >= 136) {
        return;
    }
    int tile_col = 0;
    int tile_base = 0;
    #pragma unroll
    for (int candidate = 0; candidate < 16; ++candidate) {
        if (tile_index >= tile_base + candidate + 1) {
            tile_base += candidate + 1;
            tile_col = candidate + 1;
        }
    }
    const int tile_row = tile_index - tile_base;

    const int row_origin = tile_row * 16;
    const int col_origin = tile_col * 16;
    const float* panel_base = panel
        + static_cast<long long>(sample) * panel_batch_stride
        + macro * 256;
    float* output_base = output
        + static_cast<long long>(sample) * output_batch_stride
        + static_cast<long long>(macro) * 256 * (output_leading + 1);

    wmma::fragment<wmma::accumulator, 16, 16, 8, float> accumulator;
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> prior;
    wmma::fill_fragment(accumulator, 0.0f);
    #pragma unroll
    for (int k = 0; k < 256; k += 8) {
        wmma::fragment<
            wmma::matrix_a, 16, 16, 8,
            wmma::precision::tf32, wmma::col_major
        > left;
        wmma::fragment<
            wmma::matrix_b, 16, 16, 8,
            wmma::precision::tf32, wmma::row_major
        > right;
        wmma::load_matrix_sync(
            left, panel_base + static_cast<long long>(k) * panel_leading
                + row_origin,
            panel_leading
        );
        wmma::load_matrix_sync(
            right, panel_base + static_cast<long long>(k) * panel_leading
                + col_origin,
            panel_leading
        );
        #pragma unroll
        for (int item = 0; item < left.num_elements; ++item) {
            left.x[item] = wmma::__float_to_tf32(left.x[item]);
        }
        #pragma unroll
        for (int item = 0; item < right.num_elements; ++item) {
            right.x[item] = wmma::__float_to_tf32(right.x[item]);
        }
        wmma::mma_sync(accumulator, left, right, accumulator);
    }
    wmma::load_matrix_sync(
        prior,
        output_base + static_cast<long long>(row_origin) * output_leading
            + col_origin,
        output_leading,
        wmma::mem_row_major
    );
    #pragma unroll
    for (int item = 0; item < accumulator.num_elements; ++item) {
        accumulator.x[item] = prior.x[item] - accumulator.x[item];
    }

    __shared__ __align__(16) float tiles[8][16 * 16];
    float* tile = tiles[warp];
    wmma::store_matrix_sync(
        tile, accumulator, 16, wmma::mem_row_major
    );
    __syncwarp();
    for (int index = lane; index < 16 * 16;
         index += 32) {
        const int row = index / 16;
        const int col = index - row * 16;
        if (row_origin + row <= col_origin + col) {
            output_base[
                static_cast<long long>(row_origin + row) * output_leading
                + col_origin + col
            ] = tile[index];
        }
    }
}

void grouped_diagonal_rankk_cuda(
        torch::Tensor panel, torch::Tensor output) {
    TORCH_CHECK(panel.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(panel.scalar_type() == torch::kFloat32
                && output.scalar_type() == torch::kFloat32,
                "FP32 tensors required");
    TORCH_CHECK(panel.dim() == 3 && output.dim() == 3
                && panel.size(0) == output.size(0)
                && panel.size(1) == 256
                && panel.size(2) == output.size(1)
                && output.size(1) == output.size(2)
                && panel.stride(2) == 1 && output.stride(2) == 1,
                "compatible grouped panel and trailing output required");
    const int trailing = static_cast<int>(output.size(1));
    TORCH_CHECK((trailing % 256) == 0,
                "trailing dimension must be 256 aligned");
    const int macro_count = trailing / 256;
    grouped_diagonal_rankk_kernel<<<
        dim3(17, 1, output.size(0) * macro_count), 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
    >>>(
        panel.data_ptr<float>(),
        output.data_ptr<float>(),
        macro_count,
        static_cast<int>(panel.stride(1)),
        static_cast<int>(output.stride(1)),
        panel.stride(0),

