        const int diagonal_start = row & ~255;
        const int diagonal_row = row - diagonal_start;
        const int full_vectors = diagonal_row / 4;
        float4* output_vectors = reinterpret_cast<float4*>(
            output + base + diagonal_start
        );
        for (int vector = lane; vector < full_vectors; vector += 64) {
            output_vectors[vector] = zero;
            const int second = vector + 32;
            if (second < full_vectors) {
                output_vectors[second] = zero;
            }
        }
        const int tail = full_vectors * 4;
        for (int col = tail + lane; col < diagonal_row; col += 32) {
            output[base + diagonal_start + col] = 0.0f;
        }
    }
